it('P1: tự duyệt trong hạn mức vẫn phải bị chặn (R2 độc lập với R1)', async () => {
    const dx = await taoDeXuat('HM-2026-8001', 100_000_000, 'lan');

    const res = await duyet(dx.id, 'lan');

    expect(res.statusCode).toBe(403);
    expect(res.body).toContain('Người tạo đề xuất không được tự phê duyệt');

    const sau = await layDeXuat(dx.id);
    expect(sau.trang_thai).toBe('cho_duyet');
  });

it('P2: vượt hạn mức vai dù người duyệt khác người tạo vẫn phải bị chặn (R1 độc lập với R2)', async () => {
    const dx = await taoDeXuat('HM-2026-8002', 3_000_000_000, 'lan');

    const res = await duyet(dx.id, 'hung');

    expect(res.statusCode).toBe(403);
    expect(res.body).toContain('2.000.000.000');

    const sau = await layDeXuat(dx.id);
    expect(sau.trang_thai).toBe('cho_duyet');
  });

